import heapq

def merge_k_lists(lists):
    heap = [head for head in lists if head is not None]
    heapq.heapify(heap)
    head = None
    tail = None
    while heap:
        node = heapq.heappop(heap)
        if head is None:
            head = tail = node
        else:
            tail.next = node
            tail = node
        if node.next is not None:
            heapq.heappush(heap, node.next)
    return head

