def merge_k_lists(lists):
    def merge_two(a, b):
        head = None
        tail = None
        while a is not None and b is not None:
            if a.value <= b.value:
                small = a
                a = a.next
            else:
                small = b
                b = b.next
            if head is None:
                head = tail = small
            else:
                tail.next = small
                tail = small
        rest = a if a is not None else b
        if rest is not None:
            if head is None:
                head = rest
            else:
                tail.next = rest
        return head
    merged = None
    for list_head in lists:
        merged = merge_two(merged, list_head)
    return merged
